import { createCheckoutService, createEmbeddedCheckoutMessenger } from '@bigcommerce/checkout-sdk';
import { BrowserOptions } from '@sentry/browser';
import React, { useEffect, useMemo } from 'react';
import ReactModal from 'react-modal';
import { Provider } from 'react-redux';

import { AnalyticsProvider } from '@bigcommerce/checkout/analytics';
import { ExtensionProvider } from '@bigcommerce/checkout/checkout-extension';
import { ErrorBoundary } from '@bigcommerce/checkout/error-handling-utils';
import { getLanguageService, LocaleProvider } from '@bigcommerce/checkout/locale';
import { CheckoutProvider } from '@bigcommerce/checkout/payment-integration-api';

import B3Checkout from '../b3checkout';
import '../../scss/App.scss';
import { storage } from '../b3checkout/utils';
import { createErrorLogger } from '../common/error';
import {
  createEmbeddedCheckoutStylesheet,
  createEmbeddedCheckoutSupport,
} from '../embeddedCheckout';

import Checkout from './Checkout';

export interface CheckoutAppProps {
  checkoutId: string;
  containerId: string;
  publicPath?: string;
  sentryConfig?: BrowserOptions;
  sentrySampleRate?: number;
}

const CheckoutApp = (props: CheckoutAppProps) => {
  const { containerId, sentryConfig, sentrySampleRate, publicPath } = props;

  const checkoutService = useMemo(
    () =>
      createCheckoutService({
        locale: getLanguageService().getLocale(),
        shouldWarnMutation: process.env.NODE_ENV === 'development',
      }),
    [],
  );

  const embeddedStylesheet = useMemo(() => createEmbeddedCheckoutStylesheet(), []);

  const embeddedSupport = useMemo(() => createEmbeddedCheckoutSupport(getLanguageService()), []);

  const errorLogger = useMemo(
    () =>
      createErrorLogger(
        { sentry: sentryConfig },
        {
          errorTypes: ['UnrecoverableError'],
          publicPath,
          sampleRate: sentrySampleRate || 0.1,
        },
      ),
    [],
  );

  useEffect(() => {
    const url = document.referrer ? new URL(document.referrer) : window.location;

    storage.referrer.setValue(url.origin);

    ReactModal.setAppElement(`#${containerId}`);

    return () => {
      storage.quoteCheckoutId.removeValue();
      storage.quoteDate.removeValue();
    };
  }, []);

  return (
    <Provider store={B3Checkout.store}>
      <ErrorBoundary logger={errorLogger}>
        <LocaleProvider checkoutService={checkoutService}>
          <CheckoutProvider checkoutService={checkoutService}>
            <AnalyticsProvider checkoutService={checkoutService}>
              <ExtensionProvider
                checkoutService={checkoutService}
                errorLogger={createErrorLogger()}
              >
                <Checkout
                  {...props}
                  createEmbeddedMessenger={createEmbeddedCheckoutMessenger}
                  embeddedStylesheet={embeddedStylesheet}
                  embeddedSupport={embeddedSupport}
                  errorLogger={errorLogger}
                />
              </ExtensionProvider>
            </AnalyticsProvider>
          </CheckoutProvider>
        </LocaleProvider>
      </ErrorBoundary>
    </Provider>
  );
};

export default CheckoutApp;
