import cryptoJs from './cryptoJs';

const B3StorageSchema = {
  B3RoleId: 'B3RoleId',
  B3CompanyId: 'B3CompanyId',
  B3UserId: 'B3UserId',
  B3B2BToken: 'B3B2BToken',
  B3Email: 'B3Email',
  B3CompanyStatus: 'B3CompanyStatus',
  B3CompanyName: 'B3CompanyName',
  B3AddressBookActionPermission: 'B3AddressBookActionPermission',
  B3AddressBookIsEnabled: 'B3AddressBookIsEnabled',
  B3ExtraFields: 'B3ExtraFields',
  B3IsInitDefaultAddresses: 'B3IsInitDefaultAddresses',
  B3PoNumber: 'B3PoNumber',
  B3CustomerId: 'B3CustomerId',
  B3IPComment: 'B3IPComment',
  B3FormCompanyName: 'B3FormCompanyName',
  B3PaymentsAdditionalTextFieldValue: 'B3PaymentsAdditionalTextFieldValue',
  quoteShippingMethods: 'quoteShippingMethods',
  B3OrderExtras: 'B3OrderExtras',
  B3BillingAddressExtras: 'B3BillingAddressExtras',
  B3ShippingAddressExtras: 'B3ShippingAddressExtras',
  B3DefaultAddressExtras: 'B3DefaultAddressExtras',
  B3QuoteLabel: 'B3QuoteLabel',
  B3IsInitShippingAndBillingAddress: 'B3IsInitShippingAndBillingAddress',
  IPCheckout: 'IPCheckout',
  quoteCheckoutId: 'quoteCheckoutId',
  //quote checkout uuid added in the buyer portal
  quoteCheckoutUuid: 'quoteCheckoutUuid',
  quoteDate: 'quoteDate',
  referrer: 'referrer',
  isCheckoutLogin: 'isCheckoutLogin',
  juniorCheckoutEnabled: 'juniorCheckoutEnabled',
  quoteCompanyId: 'quoteCompanyId',
  quoteCompanyName: 'quoteCompanyName',
  isEnabledAddressLabel: 'isEnabledAddressLabel',
  InvoiceVersion: 'InvoiceVersion',
  selectBillAddressId: 'selectBillAddressId',
  selectShoppingAddressId: 'selectShoppingAddressId',
  shippingQuoteAddressId: 'shippingQuoteAddressId',
  billingQuoteAddressId: 'billingQuoteAddressId',
  B2BCompanyCredit: 'B2BCompanyCredit',
  isDisabledB2BCustomAddress: 'isDisabledB2BCustomAddress',
  BCToken: 'BCToken',
};

const clear = () => {
  Object.values(B3StorageSchema).forEach((field) => {
    sessionStorage.removeItem(field);
  });
};

const getValue = function (this: any) {
  return cryptoJs.plainText(sessionStorage.getItem(this.name));
};

const setValue = function (this: any, value: string) {
  try {
    sessionStorage.setItem(this.name, cryptoJs.cipherText(value));
  } catch (error) {
    console.log(error);
  }
};

const removeValue = function (this: any) {
  sessionStorage.removeItem(this.name);
};

const mergeItemFunc = (obj: { name: string }) => ({
  ...obj,
  getValue: getValue.bind(obj),
  setValue: setValue.bind(obj),
  removeValue: removeValue.bind(obj),
});

const B3StorageFields = Object.entries(B3StorageSchema).reduce((result: any, [key, value]) => {
  result[key] = mergeItemFunc({
    name: value,
  });

  return result;
}, {});

export default {
  clear,
  ...B3StorageFields,
};
